function initTabs(){const t=document.querySelectorAll(".tab-btn"),e=document.querySelectorAll(".tab-content");t.forEach(n=>{n.addEventListener("click",()=>{t.forEach(t=>{t.classList.remove("active")}),e.forEach(t=>t.classList.remove("active")),n.classList.add("active"),document.getElementById(n.getAttribute("data-tab")).classList.add("active")})})}function initQuiz(){const t=document.getElementById("pala-quiz-form"),e=document.getElementById("quiz-result"),n={q1:"2",q2:"2"};t&&t.addEventListener("submit",i=>{i.preventDefault();let a=0;const o=new FormData(t);for(let[t,e]of o.entries())n[t]===e&&a++;const l=Object.keys(n).length;e.textContent=a===l?`🎉 Perfect! ${a}/${l}`:`You scored ${a}/${l}`,e.style.color=a===l?"green":"orange"})}function initGalleryModal(){const t=document.getElementById("gallery-modal"),e=document.getElementById("modal-title"),n=document.getElementById("modal-desc"),i=document.querySelector(".modal-close");document.querySelectorAll(".gallery-item").forEach(i=>{i.addEventListener("click",()=>{e.textContent=i.getAttribute("data-title"),n.textContent=i.getAttribute("data-desc"),t.classList.add("active")})}),i&&i.addEventListener("click",()=>t.classList.remove("active")),window.addEventListener("click",e=>{e.target===t&&t.classList.remove("active")})}function initScrollTop(){const t=document.getElementById("btn-scroll-top");t&&(window.addEventListener("scroll",()=>t.classList.toggle("visible",window.scrollY>300)),t.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"})))}function registerJourneyItems(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("pala-dynasty/index.html",[{id:"pala-vikramashila",title:"Vikramashila University",description:"Ancient center of Buddhist learning.",link:"pala-dynasty/index.html#buddhism"},{id:"pala-somapura",title:"Somapura Mahavihara",description:"Largest Buddhist vihara in subcontinent.",link:"pala-dynasty/index.html#buddhism"}])}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initQuiz(),initGalleryModal(),initScrollTop(),registerJourneyItems()});